import { createHash, randomUUID } from "node:crypto";
import { readdir, readFile, stat, writeFile, mkdir } from "node:fs/promises";
import path from "node:path";

const root = process.cwd();
const output = path.resolve(process.argv[2] ?? path.join(root, "build", "stage6-release"));
const releaseInputs = path.resolve(process.argv[3] ?? output);
const sha256 = async file => createHash("sha256").update(await readFile(file)).digest("hex");
const files = [];
async function walk(directory) {
  for (const name of (await readdir(directory)).sort()) {
    const absolute = path.join(directory, name);
    const metadata = await stat(absolute);
    if (metadata.isDirectory()) await walk(absolute);
    else if (!absolute.endsWith("ji.cdx.json") && !absolute.endsWith("ji.spdx.json")
      && !absolute.endsWith("provenance.intoto.jsonl")) {
      files.push({ absolute, name: path.relative(releaseInputs, absolute).replaceAll("\\", "/"), size: metadata.size });
    }
  }
}
await walk(releaseInputs);
const components = await Promise.all(files.map(async file => ({
  type: "file", name: file.name, hashes: [{ alg: "SHA-256", content: await sha256(file.absolute) }],
  properties: [{ name: "ji:size", value: String(file.size) }],
})));
const serial = `urn:uuid:${randomUUID()}`;
const timestamp = new Date().toISOString();
const cyclonedx = {
  bomFormat: "CycloneDX", specVersion: "1.6", serialNumber: serial, version: 1,
  metadata: { timestamp, component: { type: "application", "bom-ref": "pkg:maven/io.github.diodeme.ji/ji@0.1.0-SNAPSHOT", name: "ji", version: "0.1.0-SNAPSHOT" },
    properties: [{ name: "ji.release.public", value: "false" }] },
  components,
};
const spdx = {
  spdxVersion: "SPDX-2.3", dataLicense: "CC0-1.0", SPDXID: "SPDXRef-DOCUMENT",
  name: "ji-internal-rc", documentNamespace: `https://ji.invalid/spdx/${randomUUID()}`, creationInfo: {
    created: timestamp, creators: ["Tool: ji-stage6-sbom-generator"] },
  packages: [{ name: "ji", SPDXID: "SPDXRef-Package-ji", versionInfo: "0.1.0-SNAPSHOT",
    downloadLocation: "NOASSERTION", filesAnalyzed: true, licenseConcluded: "MIT", licenseDeclared: "MIT",
    hasFiles: components.map((_, index) => `SPDXRef-File-${index}`) }],
  files: components.map((component, index) => ({ fileName: component.name, SPDXID: `SPDXRef-File-${index}`,
    checksums: [{ algorithm: "SHA256", checksumValue: component.hashes[0].content }], licenseConcluded: "NOASSERTION" })),
  relationships: [{ spdxElementId: "SPDXRef-DOCUMENT", relationshipType: "DESCRIBES", relatedSpdxElement: "SPDXRef-Package-ji" }],
};
await mkdir(output, { recursive: true });
await writeFile(path.join(output, "ji.cdx.json"), `${JSON.stringify(cyclonedx, null, 2)}\n`);
await writeFile(path.join(output, "ji.spdx.json"), `${JSON.stringify(spdx, null, 2)}\n`);
process.stdout.write(`SBOM_COMPONENTS=${components.length}\n`);
